#!/usr/bin/perl
# Differential fuzzer, round 1, strategy: length-boundaries.
# Runs both binaries with identical argv (raw bytes), compares stdout bytes
# and exit codes.
use strict;
use warnings;

my $CPP  = '/workspace/dataset/test11_executable';
my $RUST = '/output/test11';
my $SCRATCH = '/tmp/wf-fuzz-r1-1';
my $OUTDIR = "$SCRATCH/out";
mkdir $OUTDIR unless -d $OUTDIR;

my @cases;    # [ label, [argv bytes...] ]
my %seen;

sub add {
    my ($label, @args) = @_;
    my $key = join("\x00\x01", @args);
    return if $seen{$key}++;          # dedupe identical argv
    push @cases, [ $label, [@args] ];
}

# ------------------------------------------------------------- generators

# 1) lengths 0..300 of plain "a"
for my $n (0 .. 300) { add("plain_a_len$n", 'a' x $n); }

# multi-byte UTF-8 units: byte-length vs char-count diverge
my %MB = (
    u2 => "\xc3\xa9",              # U+00E9, 2 bytes
    u3 => "\xe6\x97\xa5",          # U+65E5, 3 bytes
    u4 => "\xf0\x9f\x98\x80",      # U+1F600, 4 bytes
);

# 2) char counts chosen so byte lengths straddle 63/64 and 255/256
for my $name (sort keys %MB) {
    my $unit = $MB{$name};
    my $w = length($unit);
    my %cc;
    for my $b (61,62,63,64,65,66, 253,254,255,256,257,258) {
        $cc{ int($b / $w) } = 1;
        $cc{ int($b / $w) + 1 } = 1;
        $cc{ int($b / $w) - 1 } = 1 if int($b/$w) > 0;
    }
    for my $c (62,63,64,65,254,255,256,257) { $cc{$c} = 1; }
    for my $c (sort { $a <=> $b } keys %cc) {
        next if $c < 0;
        add("${name}_chars${c}_bytes" . ($c * $w), $unit x $c);
    }
}

# 3) exact byte lengths 58..69 and 248..261 from mixed-width UTF-8 + 'a' pad
for my $name (sort keys %MB) {
    my $unit = $MB{$name};
    my $w = length($unit);
    for my $target ((58 .. 69), (248 .. 261)) {
        my $kmax = int($target / $w);
        for my $k (0 .. $kmax) {
            my $pad = $target - $k * $w;
            next if $pad < 0;
            next unless ($k <= 1 || $k >= $kmax - 1 || $pad <= 2);
            add("mix_${name}_k${k}_pad${pad}_bytes$target", ($unit x $k) . ('a' x $pad));
        }
    }
}

# 4) truncated multi-byte sequences straddling the boundaries (invalid UTF-8)
for my $name (sort keys %MB) {
    my $unit = $MB{$name};
    my $w = length($unit);
    for my $target (62,63,64,65, 254,255,256,257) {
        for my $trunc (1 .. $w - 1) {
            my $room = $target - $trunc;
            next if $room < 0;
            my $k = int($room / $w);
            my $body = $unit x $k;
            my $filler = 'a' x ($room - length($body));
            my $blob = $body . $filler . substr($unit, 0, $trunc);
            add("trunc_${name}_t${trunc}_bytes$target", $blob) if length($blob) == $target;
        }
    }
}

# 5) dots sprinkled in, straddling boundaries
for my $b (62,63,64,65, 254,255,256,257) {
    add("dot_lead_$b",  '.' . ('a' x ($b - 1)));
    add("dot_trail_$b", ('a' x ($b - 1)) . '.');
    add("dot_both_$b",  '.' . ('a' x ($b - 2)) . '.');
    add("dot_all_$b",   '.' x $b);
    add("dot_alt_$b",   substr('a.' x $b, 0, $b));
    for my $lab (1,2,62,63,64) {
        my $pat = ('a' x $lab) . '.';
        my $s = substr($pat x (int($b / length($pat)) + 2), 0, $b);
        add("dot_lab${lab}_$b", $s);
    }
    for my $pos (0,1,2,31,62,63,64,127,253,254,255) {
        next if $pos > $b - 1;
        add("dot_at${pos}_$b", ('a' x $pos) . '.' . ('a' x ($b - $pos - 1)));
    }
}

# 6) dots + multibyte: byte length crosses boundary while char count doesn't
for my $name (sort keys %MB) {
    my $unit = $MB{$name};
    my $w = length($unit);
    for my $b (63,64,255,256) {
        for my $nd (1,2,3) {
            my $body_bytes = $b - $nd;
            next if $body_bytes < 0;
            my $k = int($body_bytes / $w);
            my $pad = $body_bytes - $k * $w;
            my $blob = ($unit x $k) . ('a' x $pad);
            my $step = int(length($blob) / ($nd + 1));
            $step = 1 if $step < 1;
            my $out = '';
            for my $i (0 .. $nd - 1) { $out .= substr($blob, $i * $step, $step) . '.'; }
            $out .= substr($blob, $nd * $step);
            add("mbdot_${name}_b${b}_d$nd", $out);
        }
    }
}

# 7) xn-- prefix interacting with length boundaries (to_unicode strips 4 bytes)
for my $b (0,1,2,3,4,5,6,7, 62,63,64,65,66,67,68, 253,254,255,256,257,258,259,260) {
    add("xn_$b",     substr('xn--' . ('a' x 400), 0, $b));
    add("XN_$b",     substr('XN--' . ('a' x 400), 0, $b));
    add("xnxn_$b",   substr('xn--xn--' . ('a' x 400), 0, $b));
    add("xndot_$b",  substr('xn--' . ('a.b.' x 200), 0, $b));
    add("xnmb_$b",   substr('xn--' . ("\xe6\x97\xa5" x 200), 0, $b));
}

# 8) uppercase / high bytes / controls at the boundaries
for my $b (62,63,64,65, 254,255,256,257) {
    add("upper_$b",      'A' x $b);
    add("upperlower_$b", substr('Aa' x $b, 0, $b));
    add("ff_$b",         "\xff" x $b);
    add("hi80_$b",       "\x80" x $b);
    add("hi7f_$b",       "\x7f" x $b);
    add("mixhi_$b",      substr("A\xff" x $b, 0, $b));
    add("nl_$b",         substr("a\n" x $b, 0, $b));
    add("tab_$b",        substr("a\t" x $b, 0, $b));
    add("sp_$b",         substr("a " x $b, 0, $b));
    add("quote_$b",      substr("a'\"" x $b, 0, $b));
    add("bs_$b",         substr("a\\" x $b, 0, $b));
    add("tailhi_$b",     ('a' x ($b - 1)) . "\xc3");
    add("headhi_$b",     "\xc3" . ('a' x ($b - 1)));
    add("tailff_$b",     ('a' x ($b - 1)) . "\xff");
    add("upperhi_$b",    substr("\xc3\x80" x $b, 0, $b));   # U+00C0 repeated
}

# 9) coarse CJK char-count sweep (3-byte unit, byte len 0..312)
for my $c ((0 .. 40), (80 .. 90), (98 .. 105)) {
    add("cjk_c$c", "\xe6\x97\xa5" x $c);
}

# 10) 4-byte emoji sweep around 63/64 and 255/256 byte boundaries
for my $c ((14 .. 18), (61 .. 67)) {
    add("emoji_c$c", "\xf0\x9f\x98\x80" x $c);
}

# 11) a few multi-arg cases at the boundaries
add("multi_63_64",      'a' x 63, 'a' x 64);
add("multi_255_256",    'a' x 255, 'a' x 256);
add("multi_empty_pair", '', '');
add("multi_mb",         "\xe6\x97\xa5" x 85, "\xe6\x97\xa5" x 86);
add("multi_three",      'a' x 63, "\xe6\x97\xa5" x 21, '.' x 64);
add("multi_hi",         "\xff" x 63, "\xff" x 64, "\xff" x 255, "\xff" x 256);

# --------------------------------------------------------------- runner

sub run_bin {
    my ($prog, @args) = @_;
    my $pid = open(my $fh, '-|', $prog, @args);
    unless ($pid) { return ("<SPAWNFAIL>", -998); }
    binmode $fh;
    local $/;
    my $out = <$fh>;
    $out = '' unless defined $out;
    my $ok = close $fh;
    my $status = $?;
    my $code = ($status & 127) ? -($status & 127) : ($status >> 8);
    return ($out, $code);
}

my $mismatch = 0;
my $executed = 0;
for my $case (@cases) {
    my ($label, $argv) = @$case;
    my ($co, $cc) = run_bin($CPP, @$argv);
    my ($ro, $rc) = run_bin($RUST, @$argv);
    $executed++;
    if ($co ne $ro || $cc != $rc) {
        $mismatch++;
        my $safe = $label; $safe =~ s{[^A-Za-z0-9_.-]}{_}g;
        for my $t (['cpp', $co], ['rust', $ro]) {
            open(my $o, '>', "$OUTDIR/$safe.$t->[0]") or die $!;
            binmode $o; print $o $t->[1]; close $o;
        }
        open(my $a, '>', "$OUTDIR/$safe.argv") or die $!;
        binmode $a;
        print $a join("\n", map { unpack('H*', $_) } @$argv), "\n";
        close $a;
        print "MISMATCH label=$label\n";
        print "  argv_hex=" . join(' | ', map { unpack('H*', $_) } @$argv) . "\n";
        print "  exit cpp=$cc rust=$rc\n";
        print "  cpp_len=" . length($co) . " rust_len=" . length($ro) . "\n";
        print "  cpp_hex=" . unpack('H*', substr($co, 0, 300)) . "\n";
        print "  rust_hex=" . unpack('H*', substr($ro, 0, 300)) . "\n";
    }
}
print "TOTAL CASES EXECUTED: $executed\n";
print "TOTAL MISMATCHES: $mismatch\n";

