#!/usr/bin/perl
# Round 1b: denser length-boundary sweep.
use strict;
use warnings;

my $CPP  = '/workspace/dataset/test11_executable';
my $RUST = '/output/test11';
my $OUTDIR = '/tmp/wf-fuzz-r1-1/out2';
mkdir $OUTDIR unless -d $OUTDIR;

my @cases; my %seen;
sub add {
    my ($label, @args) = @_;
    my $key = join("\x00\x01", @args);
    return if $seen{$key}++;
    push @cases, [ $label, [@args] ];
}

my %MB = (u2 => "\xc3\xa9", u3 => "\xe6\x97\xa5", u4 => "\xf0\x9f\x98\x80");

# A) dense: every byte length 0..320, repeated MB unit truncated to that length
#    (guarantees a split multi-byte sequence at most lengths)
for my $name (sort keys %MB) {
    my $unit = $MB{$name};
    my $big = $unit x 200;
    for my $n (0 .. 320) { add("dense_${name}_$n", substr($big, 0, $n)); }
}

# B) dense: every byte length 0..320 of a mixed ASCII+MB+dot pattern truncated
my @pats = (
    ['pat_adot',  'a.'],
    ['pat_mbdot', "\xe6\x97\xa5."],
    ['pat_mixed', "a\xc3\xa9.\xe6\x97\xa5"],
    ['pat_upmb',  "A\xf0\x9f\x98\x80."],
    ['pat_xnrep', 'xn--'],
    ['pat_hi',    "\xff\x80"],
);
for my $p (@pats) {
    my ($pn, $pat) = @$p;
    my $big = $pat x 400;
    for my $n (0 .. 320) { add("${pn}_$n", substr($big, 0, $n)); }
}

# C) dots at EVERY position, for total lengths exactly 63, 64, 255, 256
for my $b (63, 64, 255, 256) {
    for my $pos (0 .. $b - 1) {
        add("dotpos_${b}_$pos", ('a' x $pos) . '.' . ('a' x ($b - $pos - 1)));
    }
}

# D) every single byte value 0x01..0xff placed at the tail of a 63/255-byte
#    string and at the head (NUL cannot appear in argv)
for my $b (63, 64, 255, 256) {
    for my $v (1 .. 255) {
        add("tailbyte_${b}_$v", ('a' x ($b - 1)) . chr($v));
        add("headbyte_${b}_$v", chr($v) . ('a' x ($b - 1)));
    }
}

