#!/usr/bin/perl
# Round 1c: multi-arg boundaries + label-structure length sweeps.
use strict;
use warnings;

my $CPP  = '/workspace/dataset/test11_executable';
my $RUST = '/output/test11';
my $OUTDIR = '/tmp/wf-fuzz-r1-1/out3';
mkdir $OUTDIR unless -d $OUTDIR;

my @cases; my %seen;
sub add {
    my ($label, @args) = @_;
    my $key = join("\x00\x01", @args);
    return if $seen{$key}++;
    push @cases, [ $label, [@args] ];
}

my @BOUND = (0, 1, 62, 63, 64, 65, 254, 255, 256, 257);

# A) label-structure: labels of length L joined by dots, truncated to exact
#    total byte lengths around 63 and 255
for my $L (1 .. 70) {
    my $pat = ('a' x $L) . '.';
    my $big = $pat x (int(300 / length($pat)) + 3);
    for my $t ((60 .. 68), (250 .. 260)) {
        my $s = substr($big, 0, $t);
        add("lab${L}_t$t", $s);
        # same but with the trailing dot stripped / doubled
        my $s2 = $s; $s2 =~ s/\.$//;
        add("lab${L}_t${t}_nodot", $s2);
        add("lab${L}_t${t}_dbldot", $s . '.');
    }
}

# B) CJK labels: 21 chars = 63 bytes, 22 = 66 bytes
for my $c (18 .. 24) {
    my $lab = "\xe6\x97\xa5" x $c;
    add("cjklab_c$c",        $lab);
    add("cjklab_c${c}_dot",  $lab . '.');
    add("cjklab_c${c}_x2",   "$lab.$lab");
    add("cjklab_c${c}_x4",   "$lab.$lab.$lab.$lab");
    add("cjklab_c${c}_x5",   "$lab.$lab.$lab.$lab.$lab");
    add("cjklab_c${c}_xn",   'xn--' . $lab);
}

# C) xn-- with body lengths such that total or stripped length hits a boundary
for my $body (55 .. 72, 246 .. 264) {
    add("xnbody_$body",   'xn--' . ('a' x $body));
    add("xnbodyU_$body",  'XN--' . ('A' x $body));
    add("xnbodyM_$body",  'xn--' . substr("\xe6\x97\xa5" x 200, 0, $body));
    add("xnbodyD_$body",  'xn--' . substr('a.' x 200, 0, $body));
}

# D) multi-arg: 2..16 args each at a boundary length
for my $n (2, 3, 4, 8, 16) {
    for my $b (@BOUND) {
        add("marg_n${n}_b$b", map { 'a' x $b } 1 .. $n);
    }
    add("marg_n${n}_mixed", map { ('a' x 63, 'a' x 64, "\xe6\x97\xa5" x 21,
                                  "\xe6\x97\xa5" x 22, '.' x 255, '.' x 256)[$_ % 6] } 1 .. $n);
    add("marg_n${n}_empty", map { '' } 1 .. $n);
    add("marg_n${n}_hi",    map { "\xff" x (62 + $_) } 1 .. $n);
}

# E) an ascending ladder of arg lengths 0..80 in one invocation, and 240..280
add("ladder_0_80",   map { 'a' x $_ } 0 .. 80);
add("ladder_240_280", map { 'a' x $_ } 240 .. 280);
add("ladder_mb_0_40", map { substr("\xe6\x97\xa5" x 40, 0, $_) } 0 .. 40);
add("ladder_mb_240_280", map { substr("\xe6\x97\xa5" x 120, 0, $_) } 240 .. 280);
add("ladder_dots_0_80", map { '.' x $_ } 0 .. 80);

